use nocturne_native::NativeScene;
#[test] fn original_modal_long_unicode(){let mut s=NativeScene::new(2030).unwrap();let text="🙂A\\u0000אב".repeat(18001);let command=format!(r#"{{"op":"source-modal","action":"push","context":"{text}","entry":{{"id":"same","kind":"center","title":"{text}","body":"{text}","atMs":0,"dismissible":true}}}}"#);s.command(&command).unwrap();s.command(&format!(r#"{{"op":"source-modal","action":"edit","query":"{text}"}}"#)).unwrap();let info=s.infoComplete().unwrap();assert_eq!(info.matches(&text).count(),6);assert!(s.source_stage_oklch(880,900,180000).is_ok());let saved=s.snapshot().unwrap();let mut b=NativeScene::new(2030).unwrap();b.restore(&saved).unwrap();assert_eq!(saved,b.snapshot().unwrap());s.command(r#"{"op":"key","key":"Escape"}"#).unwrap();assert!(s.infoComplete().unwrap().contains("\"depth\":0"));}
